result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "backtest.py", "content": """"Walk-forward one-step-ahead backtest for three forecasters.

Every forecast at time index i is computed strictly from y[:i]
(all data prior to i); the actual value y[i] is never touched.
"""
from dataclasses import dataclass
import numpy as np

from gen import generate


def forecast_naive(history: np.ndarray) -> float:
    """Random walk: last observed value."""
    return float(history[-1])


def forecast_seasonal_naive(history: np.ndarray, lag: int = 52) -> float:
    """Seasonal naive: value from `lag` periods ago."""
    return float(history[-lag])


def forecast_ewma(history: np.ndarray, alpha: float = 0.3) -> float:
    """Simple exponential smoothing (EWMA) fitted by recursion on history."""
    s = float(history[0])
    for x in history[1:]:
        s = alpha * float(x) + (1.0 - alpha) * s
    return s


FORECASTERS = {
    "naive": forecast_naive,
    "seasonal_naive": forecast_seasonal_naive,
    "ewma": forecast_ewma,
}


@dataclass
class BacktestResult:
    timestamps: list          # integer week indices of the test window
    actuals: np.ndarray       # true values at those indices
    predictions: dict         # model name -> list of predictions

    def to_rows(self):
        """Yield (model, actual, prediction) per timestamped step."""
        for t, a in zip(self.timestamps, self.actuals):
            yield t, a


def walk_forward(y: np.ndarray, test_len: int = 40,
                 forecasters=None) -> BacktestResult:
    """Expanding-window one-step-ahead forecasts over the last `test_len` weeks."""
    if forecasters is None:
        forecasters = FORECASTERS
    n = len(y)
    start = n - test_len
    timestamps = list(range(start, n))
    predictions = {name: [] for name in forecasters}
    for t in timestamps:
        history = y[:t]  # strictly prior data only
        for name, fn in forecasters.items():
            predictions[name].append(fn(history))
    return BacktestResult(
        timestamps=timestamps,
        actuals=np.asarray(y[start:], dtype=float),
        predictions=predictions,
    )


def run(seed: int = 5) -> BacktestResult:
    return walk_forward(generate(seed=seed))


if __name__ == "__main__":
    res = run()
    print(f"test window: weeks {res.timestamps[0]}..{res.timestamps[-1]}")
    for name, preds in res.predictions.items():
        print(name, "->", [f"{p:.0f}" for p in preds[:3]], "...")
"})
